export function formatMetropolitanHoodIntlSummary(
  hood: Pick<Neighborhood, 'id' | 'name' | 'buyPerSqm' | 'rahn80m'>,
  areaUnit: AreaUnit = getStoredAreaUnit(),
  referenceCurrency: IntlCurrencyCode = getStoredIntlCurrency()
) {
  const displayUnitPriceMillion = Number(convertPricePerSqmToUnit(hood.buyPerSqm, areaUnit).toFixed(2));
  return {
    hoodId: hood.id,
    name: hood.name,
    displayUnitPriceMillion,
    displayAreaUnitLabel: formatAreaUnitLabel(areaUnit),
    buyUnitPriceIntlText: formatMillionTomanAsIntlCurrency(displayUnitPriceMillion, referenceCurrency),
    rahn80mIntlText: formatMillionTomanAsIntlCurrency(hood.rahn80m, referenceCurrency),
  };
}
